// Extraer datos del mensaje entrante de WhatsApp
const body = $input.item.json.body || {};
const messageText = (body.message || body.text || body.body || '').trim();
const fromPhone = (body.from || body.phone || body.sender || '').replace(/[^0-9]/g, '');
const pushName = body.pushName || body.senderName || 'Trabajador';

// Validar Horario en Zona Horaria de Argentina (GMT-3)
const now = new Date();
const arTimeStr = now.toLocaleTimeString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires', hour12: false });
const [hh, mm] = arTimeStr.split(':').map(Number);
const currentMinutes = hh * 60 + mm;

// Rango permitido: 06:30 (390 min) hasta 19:30 (1170 min)
const minAllowed = 6 * 60 + 30;
const maxAllowed = 19 * 60 + 30;
const isWithinAllowedTime = currentMinutes >= minAllowed && currentMinutes <= maxAllowed;

// Determinar si es llegada tarde (> 08:15)
const isLate = currentMinutes > (8 * 60 + 15);

// Determinar Quincena actual
const dayOfMonth = now.getDate();
const quincena = dayOfMonth <= 15 ? '1Q' : '2Q';
const meses = ['ENERO', 'FEBRERO', 'MARZO', 'ABRIL', 'MAYO', 'JUNIO', 'JULIO', 'AGOSTO', 'SEPTIEMBRE', 'OCTUBRE', 'NOVIEMBRE', 'DICIEMBRE'];
const mesNombre = meses[now.getMonth()];
const fechaISO = now.toISOString().split('T')[0];

return {
  fromPhone,
  pushName,
  messageText,
  timeFormatted: `${hh.toString().padStart(2, '0')}:${mm.toString().padStart(2, '0')}`,
  isWithinAllowedTime,
  isLate,
  fechaISO,
  mesNombre,
  quincena
};

